// WantsBlink reports whether an Images row or a registry-browser tag row is in
// an animated state (running, or an action observed on it), or whether the
// footer shows a load of the view's own. A queued row and a remembered failure
// are steady. It is the level the router's BlinkingView
// check reads.
func (m Model) WantsBlink() bool {
	for _, r := range m.imageTable.Items() {
		if r.Activity.State == indicator.Running {
			return true
		}
	}
	if m.registryBrowser != nil && m.registryBrowser.WantsBlink() {
		return true
	}
	// of what is still running is the least urgent of the three, and the
	// component is what enforces that order now.
	parts = append(parts, m.renderTabBar(width), theme.EmptyLineBg(width), m.footer.View(width, m.status()))
	return strings.Join(parts, "\n")
}

// status is what the view derives on every frame: the active tab's load, which
// stays first and carries no row detail, then the selected image's own activity
// composed with the running action or the batch progress. None has a timer.
func (m Model) status() sharedcomponents.Status {
	if text, ok := m.loadingLabel(); ok {
		return sharedcomponents.Status{Text: text, Activity: true}
	}
	st := sharedcomponents.Status{Text: m.actionLine()}
	if st.Text == "" {
		st.Text = sharedcomponents.JobsStatusLine(m.jobs, command.ViewOCIResources)
	}
	moving := false
	if m.activeTab == tabImages {
		if row, ok := m.imageTable.Selected(); ok {
			a := m.rowActivity(row)
			st.Detail = a.Detail
			moving = a.State == indicator.Running || a.State == indicator.Queued
		}
	}
	if st.Text == "" {
		st.Text = m.inlineSecretLine()
	}
	// Only a detail whose dot moves replaces the dot; a failed row's is fixed.
	st.Activity = len(jobs.Unfinished(m.jobs)) > 0 && (!moving || st.Detail.IsZero())
	return st
}

// inlineSecretLine says why the selected registry's Logged cell is a warning:
// its password sits in the engine's auth file, base64 encoded, which is not
// encryption (§3.68). A state rather than a message — it holds for as long as
// the row is selected, not for three seconds.
func (m Model) inlineSecretLine() string {
	if m.activeTab != tabRegistries || m.authFile == "" {
		return ""
	}
	url := ""
	if reg := m.getSelectedRegistry(); reg != nil {
		url = reg.URL
	} else if group := m.drilledGroup(); group != nil {
		url = group.URL
	}
	if m.registryLoginStatus[url] != docker.LoginInline {
		return ""
	}
	return "Password stored unencrypted in " + m.authFile + " — configure a credential helper"
}

// formStatus is the status while a form or the browser has the viewport. The
// tables behind them are not on screen, so their loads say nothing here; the
// browser's own search does.
func (m Model) formStatus() sharedcomponents.Status {
	if m.registryBrowser != nil {
		if text, ok := m.registryBrowser.LoadingLabel(); ok {
			return sharedcomponents.Status{Text: text, Activity: true}
		}
		// Past the search, the footer says what the tag under the cursor is doing.
		if row, ok := m.registryBrowser.tagTable.Selected(); ok && m.registryBrowser.state == browserStateTags {
			return sharedcomponents.Status{Detail: row.Activity.Detail}
		}
	}
	if m.networkInspectForm != nil && m.networkInspectForm.loading {
		return sharedcomponents.Status{Text: "Loading containers...", Activity: true}
	}
	if m.launchForm != nil {
		if st := m.launchForm.ValidationStatus(); st.Text != "" {
			return st
		}
	}
	return sharedcomponents.Status{}
}

